import freemarker.template.*;
import freemarker.template.utility.ObjectConstructor;
import freemarker.cache.StringTemplateLoader;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;
import javax.servlet.http.*;
import javax.servlet.*;

/**
 * NotificationTemplateService - renders user notification templates
 * with personalization data. Templates are stored per-tenant and
 * rendered server-side before delivery via email/push.
 * 
 * Security: Uses Freemarker's SAFER_RESOLVER to block dangerous builtins.
 * All template data is escaped via HTML auto-escaping.
 */
public class NotificationTemplateService extends HttpServlet {

    private final ConcurrentHashMap<String, String> templateCache = new ConcurrentHashMap<>();
    private final Configuration safeConfig;
    private final StringTemplateLoader templateLoader;

    public NotificationTemplateService() {
        // Initialize secure Freemarker configuration
        this.safeConfig = new Configuration(Configuration.VERSION_2_3_31);
        this.safeConfig.setNewBuiltinClassResolver(TemplateClassResolver.SAFER_RESOLVER);
        this.safeConfig.setAPIBuiltinEnabled(false);
        this.safeConfig.setLogTemplateExceptions(false);
        this.safeConfig.setAutoEscapingPolicy(Configuration.ENABLE_IF_DEFAULT_AUTO_ESCAPING_POLICY);
        this.templateLoader = new StringTemplateLoader();
        this.safeConfig.setTemplateLoader(templateLoader);
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp) 
            throws ServletException, IOException {
        String action = req.getParameter("action");
        String tenantId = validateTenantId(req.getHeader("X-Tenant-ID"));

        if (tenantId == null) {
            resp.sendError(403, "Invalid tenant");
            return;
        }

        if (action == null) {
            resp.sendError(400, "Missing action");
            return;
        }

        switch (action) {
            case "register":
                registerTemplate(req, resp, tenantId);
                break;
            case "preview":
                previewTemplate(req, resp, tenantId);
                break;
            case "render":
                renderNotification(req, resp, tenantId);
                break;
            default:
                resp.sendError(400, "Unknown action");
        }
    }

    /**
     * Register a new notification template for a tenant.
     * Templates are validated for syntax before storage.
     */
    private void registerTemplate(HttpServletRequest req, HttpServletResponse resp,
                                   String tenantId) throws IOException {
        String templateName = req.getParameter("name");
        String templateBody = req.getParameter("body");

        if (templateName == null || !templateName.matches("[a-zA-Z0-9_-]+")) {
            resp.sendError(400, "Invalid template name");
            return;
        }

        // Validate template syntax before storing
        if (!validateTemplateSyntax(templateBody)) {
            resp.sendError(400, "Template syntax error");
            return;
        }

        String key = tenantId + ":" + templateName;
        templateCache.put(key, templateBody);
        resp.setStatus(201);
        resp.getWriter().write("{\"status\": \"registered\"}");
    }

    /**
     * Preview a template with sample data. Uses the safe configuration
     * for all template processing including inline previews.
     */
    private void previewTemplate(HttpServletRequest req, HttpServletResponse resp,
                                  String tenantId) throws IOException {
        String templateBody = req.getParameter("body");
        String sampleDataJson = req.getParameter("data");

        if (templateBody == null || templateBody.length() > 4096) {
            resp.sendError(400, "Invalid template body");
            return;
        }

        Map<String, Object> dataModel = parseSampleData(sampleDataJson);
        dataModel.put("tenant", tenantId);

        try {
            // Use inline template for preview - with safe configuration
            String rendered = renderInlineTemplate(templateBody, dataModel);
            resp.setContentType("text/html; charset=UTF-8");
            resp.getWriter().write(rendered);
        } catch (TemplateException e) {
            resp.sendError(500, "Template rendering failed");
        }
    }

    /**
     * Render a registered template with actual notification data.
     */
    private void renderNotification(HttpServletRequest req, HttpServletResponse resp,
                                     String tenantId) throws IOException {
        String templateName = req.getParameter("name");
        String recipientData = req.getParameter("data");

        if (templateName == null || !templateName.matches("[a-zA-Z0-9_-]+")) {
            resp.sendError(400, "Invalid template name");
            return;
        }

        String key = tenantId + ":" + templateName;
        String templateBody = templateCache.get(key);

        if (templateBody == null) {
            resp.sendError(404, "Template not found");
            return;
        }

        Map<String, Object> dataModel = parseSampleData(recipientData);
        dataModel.put("tenant", tenantId);

        try {
            // Registered templates use the cached loader path
            templateLoader.putTemplate(key, templateBody);
            Template template = safeConfig.getTemplate(key);
            StringWriter out = new StringWriter();
            template.process(dataModel, out);
            resp.setContentType("text/html; charset=UTF-8");
            resp.getWriter().write(out.toString());
        } catch (TemplateException e) {
            resp.sendError(500, "Rendering failed");
        }
    }

    /**
     * Renders an inline template for preview purposes.
     * Uses the safe configuration to prevent dangerous builtins.
     */
    private String renderInlineTemplate(String templateBody, Map<String, Object> dataModel) 
            throws IOException, TemplateException {
        // Create template directly from string using safe configuration
        Template inlineTemplate = new Template(
            "inline_preview", 
            new StringReader(templateBody),
            safeConfig  // use safe configuration for inline previews
        );
        StringWriter writer = new StringWriter();
        inlineTemplate.process(dataModel, writer);
        return writer.toString();
    }

    /**
     * Validates template syntax without executing it.
     */
    private boolean validateTemplateSyntax(String body) {
        if (body == null || body.isEmpty()) return false;
        try {
            new Template("validation", new StringReader(body), safeConfig);
            return true;
        } catch (Exception e) {
            return false;
        }
    }

    private String validateTenantId(String tenantId) {
        if (tenantId == null) return null;
        if (tenantId.matches("[a-zA-Z0-9]{4,32}")) return tenantId;
        return null;
    }

    private Map<String, Object> parseSampleData(String json) {
        // Simplified JSON parsing - in production would use Jackson
        Map<String, Object> result = new HashMap<>();
        if (json == null) return result;
        // Parse simple key-value pairs from JSON
        json = json.trim();
        if (json.startsWith("{") && json.endsWith("}")) {
            json = json.substring(1, json.length() - 1);
            String[] pairs = json.split(",");
            for (String pair : pairs) {
                String[] kv = pair.split(":", 2);
                if (kv.length == 2) {
                    String k = kv[0].trim().replaceAll("\"", "");
                    String v = kv[1].trim().replaceAll("\"", "");
                    if (k.matches("[a-zA-Z0-9_]+")) {
                        result.put(k, v);
                    }
                }
            }
        }
        return result;
    }
}
